const data=[['네온테트라','열대어','약 2cm · 5마리',6500,2,'live'],['옐로우 구피','구피','준성어 · 1쌍',12000,5,'live'],['체리새우','관상새우','약 1.5cm · 10마리',9000,12,'live'],['피그미 코리도라스','열대어','약 2cm · 3마리',15000,20,'live'],['백색 메다카','메다카','성어 · 5마리',18000,40,'live'],['아누비아스 나나','수초','소형 포트 · 1개',7000,65,'live'],['스펀지 여과기','여과기','소형 · 1개',8000,3,'gear'],['세라믹 여과재','여과재','1L · 1봉',14000,6,'gear'],['열대어 사료','사료','100g · 1통',11000,10,'gear'],['수조용 히터','히터','50W · 1개',22000,18,'gear'],['수초용 LED 조명','조명','30cm · 1개',39000,42,'gear'],['유리 수조','수조','30×30×30cm · 1개',45000,70,'gear']].map(([name,cat,spec,price,age,type])=>({name,cat,spec,price,age,type}));
let type='live',sort='low',query='';
function art(t,i){return t==='live'?`<svg viewBox="0 0 160 110" aria-hidden="true"><path d="M24 55Q74 0 120 55Q74 110 24 55Z" fill="${['#65927b','#cca765','#b77363'][i%3]}"/><path d="M116 55L150 24V86Z" fill="#90ac85"/><circle cx="47" cy="47" r="4" fill="#24473c"/><path d="M79 29Q105 55 79 81" fill="none" stroke="#ffffff70" stroke-width="3"/></svg>`:`<svg viewBox="0 0 160 110" aria-hidden="true"><rect x="46" y="23" width="67" height="72" rx="12" fill="#90a897"/><rect x="50" y="12" width="59" height="20" rx="5" fill="#416653"/><rect x="57" y="43" width="45" height="30" rx="4" fill="#e6eed9"/><path d="M67 58h25M67 65h16" stroke="#7a956d" stroke-width="3"/></svg>`;}
function render(){const days=+document.querySelector('#period').value;let rows=data.filter(x=>x.type===type&&x.age<=days&&x.name.toLowerCase().includes(query.toLowerCase()));rows.sort(sort==='high'?(a,b)=>b.price-a.price:sort==='new'?(a,b)=>a.age-b.age:(a,b)=>a.price-b.price);document.querySelector('#resultTitle').textContent=`${type==='live'?'생물':'용품'} ${sort==='sales'?'':rows.length+'개'}`;document.querySelector('#resultNote').textContent=type==='live'?'같은 품종·크기·수량인지 확인하세요':'같은 모델·규격·구성인지 확인하세요';const grid=document.querySelector('#grid');if(sort==='sales'){grid.innerHTML='<div class="empty"><strong>판매량 데이터가 필요해요</strong>선택 기간의 실제 판매량을 제공하는 판매처가 연결되면 표시합니다.<br>판매량을 추정하거나 임의 순위를 만들지 않습니다.</div>';return;}if(!rows.length){grid.innerHTML='<div class="empty"><strong>조건에 맞는 샘플이 없어요</strong>검색어를 바꾸거나 조회 기간을 늘려보세요.</div>';return;}grid.innerHTML=rows.map((x,i)=>`<article class="card"><div class="art" style="background:${['#e4ecdf','#eeeadd','#e6ede9'][i%3]}"><span class="badge">샘플 이미지</span>${art(type,i)}</div><div class="body"><div class="category">${x.cat}</div><h3>${x.name}</h3><div class="spec">${x.spec}</div><div class="price">${x.price.toLocaleString('ko-KR')}<small> 원</small></div><div class="spec">가상 가격 · 배송비 미반영</div><div class="meta"><span>샘플 판매처 ${i+1}</span><span>등록 ${x.age}일 전 · 가상 날짜</span></div></div></article>`).join('');}
document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{type=b.dataset.type;document.querySelectorAll('[data-type]').forEach(a=>{const on=a===b;a.classList.toggle('active',on);a.setAttribute('aria-pressed',on);a.querySelector('.check').textContent=on?'✓':''});render()}));document.querySelectorAll('[data-sort]').forEach(b=>b.addEventListener('click',()=>{sort=b.dataset.sort;document.querySelectorAll('[data-sort]').forEach(a=>{a.classList.toggle('active',a===b);a.setAttribute('aria-pressed',a===b)});render()}));document.querySelector('#period').addEventListener('change',render);document.querySelector('#search').addEventListener('submit',e=>{e.preventDefault();query=document.querySelector('#query').value.trim();render()});document.querySelector('#query').addEventListener('input',e=>{query=e.target.value.trim();render()});render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_product_filters',description:'샘플 상품 목록의 종류, 정렬, 등록 기간과 검색어를 변경합니다. 실제 가격은 아닙니다.',inputSchema:{type:'object',properties:{type:{enum:['live','gear']},sort:{enum:['low','high','sales','new']},days:{enum:[7,30,90]},query:{type:'string'}},required:['type','sort','days'],additionalProperties:false},annotations:{readOnlyHint:false},execute(v){if(!v||!['live','gear'].includes(v.type)||!['low','high','sales','new'].includes(v.sort)||![7,30,90].includes(v.days)||(v.query!==undefined&&typeof v.query!=='string'))throw Error('잘못된 조회 조건');document.querySelector(`[data-type="${v.type}"]`).click();document.querySelector(`[data-sort="${v.sort}"]`).click();document.querySelector('#period').value=String(v.days);document.querySelector('#query').value=v.query||'';query=v.query||'';render();return {sample:true,type,sort,days:v.days,count:document.querySelectorAll('.card').length,salesDataAvailable:false}}})).catch(()=>{})}catch(e){}}
